public final class ArmyBehaviors {
    public interface Behavior {
        boolean allows(int id);
        int choose(LivingEntity target,long now);
        void impact(SkillDefinition skill,int frame);
        void move(LivingEntity target,long now);
        default boolean canStart(int id,LivingEntity target){return true;}
        default void started(int id,LivingEntity target){}
        default void tick(long now){}
        default void died(DamageSource source){}
        default void tickDead(long now){}
        default void hookHit(LivingEntity target){}
        default void hurtAccepted(DamageSource source,boolean frontal){}
        default void hurtAccepted(DamageSource source,boolean frontal,float healthLost){hurtAccepted(source,frontal);}
        default boolean evade(DamageSource source){return false;}
        default boolean canInterrupt(){return true;}
        default boolean preventFatal(DamageSource source,float damage){return false;}
        default CompoundTag save(){return new CompoundTag();}
        default void load(CompoundTag tag){}
        default String animation(int id){return switch(id){case ArmySkills.BRACE->"brace";case ArmySkills.ROLL->"roll";
            case ArmySkills.GRAPPLE->"grapple";case ArmySkills.KNEE->"knee";case ArmySkills.DETONATE->"detonate";
            case ArmySkills.SCORPION_EMERGE->"emerge";case ArmySkills.SCORPION_SONG->"song";case ArmySkills.TREE_WAKE->"wake";case ArmySkills.TREE_ROOTS->"roots";case ArmySkills.TOAD_LEAP->"leap";case ArmySkills.TOAD_BURST->"burst";case ArmySkills.SKULL_BLOOD->"blood";case ArmySkills.PAPER_SHED->"shed";case ArmySkills.CHILD_CURSE->"curse";case ArmySkills.AXE_COUNTER->"counter";case ArmySkills.GHOST_PHASE->"phase";default->"attack";};}
    }
    static Behavior create(TemplateMob mob,TemplateMob.Kind kind){return switch(kind){
        case PALANQUIN->new PalanquinBehavior(mob);case YECHA->new YechaBehavior(mob);case CENTIPEDE->new CentipedeBehavior(mob);case BIXI->new BixiBehavior(mob);case DROWNER->new DrownerBehavior(mob);case BLIND_FISH->new BlindFishBehavior(mob);case LANTERN_BAT->new LanternBatBehavior(mob);case MINING_SPIDER->new MiningSpiderBehavior(mob);case BRONZE_SNAKE->new BronzeSnakeBehavior(mob);case CLOCKWORK_DOG->new ClockworkDogBehavior(mob);case STONE_GUARD->new StoneGuardBehavior(mob);case SERPENT->new WaterSerpentBehavior(mob);case SPEAR->new Spear(mob);case CROSSBOW->new Crossbow(mob);case SCOUT->new Scout(mob);
        case POWDER->new Powder(mob);case FLAG->new Flag(mob);case AXE_GUARD->new AxeGuard(mob);case GHOST->new Ghost(mob);case CORPSE->new Corpse(mob);case CHILD->new ShroudChild(mob);case PAPER->new PaperSwordsman(mob);case SKULL->new FlyingSkull(mob);case TOAD->new RedToad(mob);case TREE->new TreeSpirit(mob);case SCORPION->new SandScorpion(mob);default->null;};}

private static final class PaperSwordsman extends Base {
    long substitutionUntil;boolean substituting;
    PaperSwordsman(TemplateMob mob){super(mob);}
    public boolean allows(int id){return id==ArmySkills.PAPER_SLASH||id==ArmySkills.PAPER_SHED;}
    public boolean canStart(int id,LivingEntity target){return id!=ArmySkills.PAPER_SHED||substituting;}
    public int choose(LivingEntity target,long now){
        return mob.tombSignal.target(mob)==target&&!TombEncounterCoordinator.inFront(mob,target)?0:ArmySkills.PAPER_SLASH;
    }
    public void tick(long now){if(mob.getTarget()==null||!mob.getTarget().isAlive()||mob.skillId()!=0)mob.setSprinting(false);}
    public void move(LivingEntity target,long now){
        mob.setSprinting(true);
        if(mob.tombSignal.target(mob)==target){navigate(TombEncounterCoordinator.flank(target,false),1.25);return;}
        Vec3 forward=target.position().subtract(mob.position()).multiply(1,0,1).normalize();
        double side=((now/20+mob.getId())&1)==0?1.5:-1.5;
        Vec3 next=mob.distanceToSqr(target)>16?mob.position().add(forward.scale(3)).add(-forward.z*side,0,forward.x*side):target.position();
        navigate(next,1.25);
    }
    public void impact(SkillDefinition skill,int frame){
        if(skill.id()!=ArmySkills.PAPER_SLASH)return;
        for(var target:CombatGeometry.query(level(),mob.position(),mob.attack().direction(),CombatGeometry.Shape.SECTOR,
                skill.maxRange(),1,skill.angleDegrees(),1.6,e->mob.validEnemy(e)&&mob.hasLineOfSight(e))){
            if(target.hurt(mob.damageSources().mobAttack(mob),(float)mob.getAttributeValue(Attributes.ATTACK_DAMAGE)))
                //60 ticks gives a real delayed damage tick after the slash's invulnerability window.
                target.addEffect(new MobEffectInstance(MobEffects.WITHER,60,0),mob);
            if(!mob.isAlive()||mob.attack().current()!=skill)return;
        }
    }
    public boolean preventFatal(DamageSource source,float damage){
        long now=level().getGameTime();
        if(damage<mob.getHealth()||now<substitutionUntil||source.is(DamageTypeTags.BYPASSES_INVULNERABILITY))return false;
        LivingEntity target=source.getEntity() instanceof LivingEntity living?living:mob.getTarget();
        if(!mob.validEnemy(target)||mob.distanceToSqr(target)>256)return false;
        Vec3 landing=paperLanding(mob,target);if(landing==null)return false;
        Vec3 origin=mob.position();substitutionUntil=now+1200;mob.cancelAction();mob.setHealth(Math.max(1,mob.getHealth()));
        mob.teleportTo(landing.x,landing.y,landing.z);mob.setDeltaMovement(Vec3.ZERO);mob.setTarget(target);
        // One ordinary action epoch synchronizes the re-form clip to all trackers.
        mob.attack().endStun(now);substituting=true;
        try {mob.startSkill(ArmySkills.PAPER_SHED,target);} finally {substituting=false;}
        level().sendParticles(new net.minecraft.core.particles.ItemParticleOption(net.minecraft.core.particles.ParticleTypes.ITEM,
            new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.PAPER)),origin.x,origin.y+.8,origin.z,18,.25,.6,.12,.025);
        mob.playSound(SoundEvents.BOOK_PAGE_TURN,.8F,.6F);return true;
    }
    public CompoundTag save(){var tag=new CompoundTag();tag.putLong("SubstitutionUntil",substitutionUntil);return tag;}
    public void load(CompoundTag tag){substitutionUntil=Math.min(level().getGameTime()+1200,Math.max(0,tag.getLong("SubstitutionUntil")));}
}
/** Nine bounded candidate columns: directly behind, then either rear diagonal. Never loads chunks. */
static Vec3 paperLanding(TemplateMob mob,LivingEntity target){
    var level=(ServerLevel)mob.level();Vec3 forward=target.getLookAngle().multiply(1,0,1).normalize();
    if(forward.lengthSqr()<.001)return null;
    for(double angle:new double[]{0,Math.PI/4,-Math.PI/4})for(int dy:new int[]{0,1,-1}){
        Vec3 back=forward.yRot((float)angle).scale(-5),candidate=target.position().add(back).add(0,dy,0);
        var pos=net.minecraft.core.BlockPos.containing(candidate);candidate=new Vec3(candidate.x,pos.getY(),candidate.z);
        var box=mob.getType().getDimensions().makeBoundingBox(candidate.x,candidate.y,candidate.z);
        if(!level.hasChunkAt(pos)||!level.hasChunkAt(net.minecraft.core.BlockPos.containing(box.minX,box.minY,box.minZ))
                ||!level.hasChunkAt(net.minecraft.core.BlockPos.containing(box.maxX,box.maxY,box.maxZ))
                ||!level.getWorldBorder().isWithinBounds(box)||!level.getFluidState(pos).isEmpty()
                ||!com.dynasty.entity.DynastySpawnPlacement.hasStandingSpace(level,pos,box)
                ||!level.getEntitiesOfClass(LivingEntity.class,box,e->e!=mob&&e.isAlive()).isEmpty())continue;
        var line=level.clip(new net.minecraft.world.level.ClipContext(target.getEyePosition(),candidate.add(0,mob.getEyeHeight(),0),
            net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,mob));
        if(line.getType()==net.minecraft.world.phys.HitResult.Type.MISS)return candidate;
    }
    return null;
}

package com.dynasty.blueprint;

import net.minecraftforge.event.entity.living.LivingDamageEvent;
import net.minecraftforge.eventbus.api.EventPriority;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

/** Final post-armour damage, before vanilla commits health loss/death/loot. */
@Mod.EventBusSubscriber(modid="dynasty")
public final class PaperSubstitution {
    private PaperSubstitution(){}
    @SubscribeEvent(priority=EventPriority.LOWEST)
    public static void damage(LivingDamageEvent event){
        if(!event.getEntity().level().isClientSide && event.getEntity() instanceof TemplateMob mob
                && mob.preventPaperFatal(event.getSource(),event.getAmount()))
            event.setAmount(Math.min(event.getAmount(),Math.max(0,mob.getHealth()-1)));
    }
}

/** The same validation gates AI and operator/GameTest starts; no client can request a damage frame. */
public boolean startSkill(int id, LivingEntity target) {
    if (level().isClientSide || !isAlive() || isRemoved() || !allows(id)) return false;
    SkillDefinition base = TemplateSkills.byId(id);
    if (base == null || (id == ArmySkills.SCORPION_EMERGE && target == this ? false : id == TemplateSkills.POSSESSION ? !validSupport(target) : !validEnemy(target))) return false;
    double range = distanceTo(target);
    if (range < base.minRange() || range > (id == ArmySkills.AXE_COUNTER ? 40 : base.maxRange()) || id != ArmySkills.SCORPION_EMERGE && base.requiresSight() && !hasLineOfSight(target)) return false;
    if (id == TemplateSkills.ROCK_THROW && !onHighGround(target)) return false;
    if (army != null && !army.canStart(id,target)) return false;
    Vec3 direction = target.position().subtract(position()).multiply(1, 0, 1).normalize();
    if (direction.lengthSqr() < .0001) direction = getLookAngle().multiply(1, 0, 1).normalize();
    // A fuse uses real elapsed time, not attack speed: three consecutive close seconds.
    float speed = id != ArmySkills.DETONATE && id != ArmySkills.AXE_COUNTER && id != ArmySkills.CHILD_CURSE && id != ArmySkills.SKULL_DIVE && id != ArmySkills.SKULL_BLOOD && id != ArmySkills.TOAD_LEAP && id != ArmySkills.SERPENT_COIL && id != ArmySkills.SERPENT_BITE && id != ArmySkills.STONE_SLAM && id != ArmySkills.STONE_UPPERCUT && id != ArmySkills.DOG_BITE && id != ArmySkills.DOG_ALARM && kind != Kind.BRONZE_SNAKE && kind != Kind.MINING_SPIDER && kind != Kind.LANTERN_BAT && kind != Kind.BLIND_FISH && kind != Kind.DROWNER && kind != Kind.BIXI && kind != Kind.CENTIPEDE && kind != Kind.YECHA && kind != Kind.PALANQUIN && hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()) ? 1.3F : 1F;
    SkillDefinition effective = TemplateSkills.accelerated(base, speed);
    if (!attack.tryStart(effective, level().getGameTime(), position(), direction, target.getUUID())) return false;
    if(army!=null)army.started(id,target);
    entityData.set(SPEED, speed);
    coverUntil = 0;
    entityData.set(SKILL, id); entityData.set(START, attack.started()); entityData.set(PHASE, AttackState.WINDUP.ordinal());
    navigation.stop(); face(direction);
    if (id == TemplateSkills.POSSESSION) entityData.set(BUFF_TARGET, target.getId());
    if (id == TemplateSkills.POUNCE) {
        Vec3 towards = target.position().subtract(position()).multiply(1, 0, 1);
        leapDestination = position().add(towards.normalize().scale(Math.min(5.6, towards.length())));
    }
    BlueprintVisualEvent.start(this, effective, attack.origin(), attack.direction(), target.getId());
    playSound(kind == Kind.BEAST ? SoundEvents.FOX_AGGRO : kind == Kind.PRIEST ? SoundEvents.EVOKER_PREPARE_ATTACK : SoundEvents.PLAYER_ATTACK_SWEEP,
            .6F, kind == Kind.SHIELD ? .65F : 1F);
    return true;
}
private boolean allows(int id) {
    return switch (kind) {
        case SWORD -> id == TemplateSkills.SWORD_COMBO;
        case SHIELD -> id == TemplateSkills.SHIELD_COMBO;
        case PRIEST -> id == TemplateSkills.TALISMAN_VOLLEY || id == TemplateSkills.POSSESSION;
        case BEAST -> id == TemplateSkills.POUNCE || id == TemplateSkills.ROCK_THROW;
        default -> army != null && army.allows(id);
    };
}

public void interruptAttack(int stunTicks) {
    if (level().isClientSide || !isAlive()) return;
    if (army != null && !army.canInterrupt()) return;
    int duration=hasEffect(BlueprintEntities.JUNHUN_AURA.get())?Math.max(1,stunTicks/2):stunTicks;
    attack.stun(level().getGameTime(), duration); finishAction(); entityData.set(PHASE, AttackState.STUN.ordinal());
}
/** Cancel both the server clock and its tracked animation, including a failed follow-up start. */
void cancelAction() {
    if (level().isClientSide) return;
    attack.cancel(); finishAction(); entityData.set(PHASE, attack.state(level().getGameTime()).ordinal());
}
private void finishAction() {
    entityData.set(SKILL, 0); entityData.set(START, -1L); entityData.set(SPEED, 1F);
    syncHook(null,-1);
    if (linkUntil == 0) entityData.set(BUFF_TARGET, -1);
    BlueprintVisualEvent.cancel(this);
}
private void face(Vec3 direction) {
    if(kind==Kind.BRONZE_SNAKE&&(skillId()==ArmySkills.BRONZE_REAR_STAB||skillId()==ArmySkills.BRONZE_POISON))direction=direction.scale(-1);
    float yaw = (float)(Math.atan2(direction.z, direction.x) * 180 / Math.PI) - 90;
    setYRot(yaw); yBodyRot = yaw; yHeadRot = yaw;
}

@Override public boolean hurt(DamageSource source, float amount) {
    if (level().isClientSide) return false;
    if (amount > 0 && isAlive() && army != null && army.evade(source)) return false;
    Entity direct = source.getDirectEntity();
    boolean projectile = source.is(DamageTypeTags.IS_PROJECTILE) || direct instanceof Projectile;
    Vec3 sourcePosition = direct == null ? source.getSourcePosition() : direct.position();
    boolean frontal = sourcePosition != null && CombatGeometry.inFront(position(), getLookAngle(), sourcePosition, 120);
    if (kind == Kind.SHIELD && frontal) {
        if (projectile) {
            if (direct instanceof Projectile) direct.discard();
            playSound(SoundEvents.SHIELD_BLOCK, .7F, .7F); return false;
        }
        if (direct instanceof LivingEntity && source.getEntity() == direct) amount *= .2F;
    }
    if (!isAlive()) return false;
    if (kind == Kind.SWORD && formation && direct instanceof AbstractArrow) amount *= .8F;
    float before=getHealth();
    boolean damaged = super.hurt(source, amount);
    if (damaged && isAlive() && army != null) army.hurtAccepted(source, frontal, Math.max(0,before-getHealth()));
    if (damaged && isAlive() && attack.current() != null && attack.current().interruptible()
            && attack.state(level().getGameTime()) == AttackState.WINDUP && amount >= Math.max(3, getMaxHealth() * .08F))
        interruptAttack(10);
    return damaged;
}
public boolean preventPaperFatal(DamageSource source,float damage) {
    return kind==Kind.PAPER && !level().isClientSide && isAlive() && army.preventFatal(source,damage);
}

@Override public void die(DamageSource source) {
    if (deathStarted >= 0) return;
    super.die(source);
    if (!isDeadOrDying()) return;
    if(kind==Kind.SKULL||kind==Kind.LANTERN_BAT||kind==Kind.BLIND_FISH||kind==Kind.YECHA)setNoGravity(false);
    deathStarted = level().getGameTime(); attack.cancel(); navigation.stop(); setTarget(null); releaseSupport(); clearPossession();
    syncHook(null,-1);
    entityData.set(CLIMBING, false);
    if(kind==Kind.MINING_SPIDER||kind==Kind.CENTIPEDE)setNoGravity(false);
    clearClimbContact();
    entityData.set(SKILL, 0); entityData.set(START, deathStarted); entityData.set(SPEED, 1F);
    BlueprintVisualEvent.cancel(this);
    BlueprintVisualEvent.death(this);
    if(!level().isClientSide&&army!=null)army.died(source);
}
public int deathDuration() { return kind == Kind.PAPER ? 10 : kind == Kind.SHIELD ? 200 : kind == Kind.SWORD ? 60 : 44; }
void onArmyHookHit(LivingEntity target,long epoch) {
    if(!level().isClientSide&&army!=null&&isAlive()&&skillId()==ArmySkills.GRAPPLE&&skillStartTime()==epoch)
        army.hookHit(target);
}
@Override protected void dropAllDeathLoot(DamageSource source) {
    if (lootDropped) return;
    lootDropped = true; super.dropAllDeathLoot(source);
}
@Override protected void tickDeath() {
    ++deathTime;
    if(!level().isClientSide&&army!=null)army.tickDead(level().getGameTime());
    if (!level().isClientSide && deathStarted >= 0)
        deathTime = (int)Math.min(240, Math.max(deathTime, level().getGameTime() - deathStarted));
    if (kind == Kind.SHIELD) setDeltaMovement(Vec3.ZERO);
    else if(!level().isClientSide&&!isNoGravity()){
        // LivingEntity stops ordinary travel once dead. Gravity alone cannot drop a flying
        // corpse or a ceiling climber; keep the normal block/world-border collision path.
        var velocity=getDeltaMovement();
        if(onGround())setDeltaMovement(Vec3.ZERO);
        else{
            setDeltaMovement(velocity.x*.8,Math.max(-.8,velocity.y-.08),velocity.z*.8);
            move(net.minecraft.world.entity.MoverType.SELF,getDeltaMovement());
            if(onGround())setDeltaMovement(Vec3.ZERO);
        }
    }
    int duration = deathDuration();
    if (deathTime >= duration && !level().isClientSide && !isRemoved()) {
        level().broadcastEntityEvent(this, (byte)60); remove(RemovalReason.KILLED);
    }
}

@Override public void addAdditionalSaveData(CompoundTag tag) {
    super.addAdditionalSaveData(tag);
    tag.putString("BlueprintEncounterSite",encounterSite);
    tag.put("TombTacticalSignal", tombSignal.save());
    if(kind==Kind.CLOCKWORK_DOG&&hasRestriction())tag.putLong("ClockworkPatrolHome",getRestrictCenter().asLong());
    tag.putBoolean("Burrowed",burrowed());
    tag.putBoolean("TreeAwake",treeAwake());tag.putFloat("TongueReach",tongueReach()); tag.put("BlueprintAttack", attack.save()); tag.putFloat("BlueprintSpeed", skillSpeed());
    tag.putBoolean("BlueprintLootDropped", lootDropped); tag.putLong("BlueprintDeathStart", deathStarted); tag.putInt("BlueprintDeathTicks", deathTime);
    tag.putLong("PossessedUntil", possessedUntil); tag.putLong("LinkUntil", linkUntil);
    if (possessor != null) tag.putUUID("Possessor", possessor);
    if (possessedAlly != null) tag.putUUID("PossessedAlly", possessedAlly);
    tag.putDouble("LeapX", leapDestination.x); tag.putDouble("LeapY", leapDestination.y); tag.putDouble("LeapZ", leapDestination.z);
    if(army!=null)tag.put("ArmyActionState",army.save());
}
@Override public void readAdditionalSaveData(CompoundTag tag) {
    super.readAdditionalSaveData(tag);
    encounterSite=tag.getString("BlueprintEncounterSite");if(encounterSite.length()>256)encounterSite="";
    tombSignal.load(tag.getCompound("TombTacticalSignal"), level().getGameTime());
    if(kind==Kind.CLOCKWORK_DOG&&tag.contains("ClockworkPatrolHome"))restrictTo(BlockPos.of(tag.getLong("ClockworkPatrolHome")),12);
    setBurrowed(tag.getBoolean("Burrowed"));
    setTreeAwake(tag.getBoolean("TreeAwake"));
    setTongueReach(tag.contains("TongueReach")?tag.getFloat("TongueReach"):5);
    float speed = tag.getFloat("BlueprintSpeed") > 1 ? 1.3F : 1F;
    entityData.set(SPEED, speed);
    attack.load(tag.getCompound("BlueprintAttack"), id -> {
        SkillDefinition def = TemplateSkills.byId(id); return def != null && allows(id) ? TemplateSkills.accelerated(def, speed) : null;
    }, level().getGameTime());
    entityData.set(SKILL, attack.current() == null ? 0 : attack.current().id()); entityData.set(START, attack.started());
    entityData.set(PHASE, attack.state(level().getGameTime()).ordinal());
    lootDropped = tag.getBoolean("BlueprintLootDropped"); deathStarted = tag.contains("BlueprintDeathStart") ? tag.getLong("BlueprintDeathStart") : -1;
    deathTime = Math.max(0, tag.getInt("BlueprintDeathTicks"));
    if (isDeadOrDying()) { attack.cancel(); entityData.set(SKILL, 0); entityData.set(START, deathStarted); }
    possessor = tag.hasUUID("Possessor") ? tag.getUUID("Possessor") : null;
    possessedAlly = tag.hasUUID("PossessedAlly") ? tag.getUUID("PossessedAlly") : null;
    possessedUntil = tag.getLong("PossessedUntil"); linkUntil = tag.getLong("LinkUntil");
    if (possessedUntil > 0 && level().getGameTime() >= possessedUntil) clearPossession();
    entityData.set(POSSESSED, hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()));
    LivingEntity ally = resolve(possessedAlly); if (ally != null) entityData.set(BUFF_TARGET, ally.getId());
    leapDestination = new Vec3(tag.getDouble("LeapX"), tag.getDouble("LeapY"), tag.getDouble("LeapZ"));
    if(encounterSite.isBlank()&&level() instanceof ServerLevel server){
        // Upgrade old structure members once on load, using the existing persisted UUID ledger.
        for(var marker:BlueprintSpawnState.get(server).markers.values())if(marker.members.contains(getUUID())){bindEncounter(marker.key);break;}
    }
    BlueprintSpawns.restoreRaidAllegiance(this); // Upgrade prior saved raid members that had split ecology allegiance.
    if(army!=null)army.load(tag.getCompound("ArmyActionState"));
}

public String visualAnimation() {
    if (isDeadOrDying()) return "death";
    if(kind==Kind.SCORPION&&burrowed())return "burrow";
    if(kind==Kind.TREE&&!treeAwake())return "camouflage";
    if (hurtTime > 0 && skillId() == 0) return "hurt";
    if(army!=null&&skillId()!=0)return army.animation(skillId());
    if (skillId() == TemplateSkills.POSSESSION) return "buff";
    if (skillId() == TemplateSkills.ROCK_THROW) return "rock";
    if (skillId() == TemplateSkills.POUNCE) return "skill";
    if (skillId() != 0) return "attack";
    if (kind == Kind.BEAST && onClimbable() && climbFace() != null) return "climb";
    if(kind==Kind.BRONZE_SNAKE&&onClimbable())return "climb";
    if (getDeltaMovement().horizontalDistanceSqr() > .001) return isSprinting() ? "run" : "walk";
    return "idle";
}
public AnimationProfile animationProfile(){return AnimationProfile.forKind(kind);}
@Override public AnimatableInstanceCache getAnimatableInstanceCache() { return animationCache; }
@Override public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
    controllers.add(new AnimationController<TemplateMob>(this, "body", 0, state -> {
        String animation = visualAnimation();
        state.getController().setAnimationSpeed(animationProfile().playbackRate(animation,getDeltaMovement().horizontalDistance(),getAttributeValue(Attributes.MOVEMENT_SPEED),isSprinting()));
        animationPartial = state.getPartialTick();
        if (lastAnimationStart != skillStartTime()) {
            lastAnimationStart = skillStartTime(); state.getController().forceAnimationReset();
        }
        RawAnimation sequence = RawAnimation.begin();
        String key = "animation." + blueprintId() + "." + animation;
        return state.setAndContinue(animationProfile().loops(animation)
                ? sequence.thenLoop(key) : sequence.thenPlayAndHold(key));
    }) {
        @Override protected double adjustTick(double tick) {
            boolean resetting = shouldResetTick;
            double local = super.adjustTick(tick);
            // GeckoLib polls a new queued clip only at transition tick zero. Replacing that
            // zero with a nonzero server age leaves the old idle clip installed forever.
            if (resetting || getAnimationState() != AnimationController.State.RUNNING) return local;
            if (kind == Kind.BEAST && climbFace() != null && climbStartTime() >= 0 && skillId() == 0 && isAlive())
                return Math.max(0, level().getGameTime() - climbStartTime() + animationPartial);
            // Late observers seek to the authoritative contact frame instead of restarting the clip.
            return skillStartTime() >= 0 && (skillId() != 0 || isDeadOrDying()) ? actionAge(animationPartial) : local;
        }
    });
}

package com.dynasty.blueprint.client;

import com.dynasty.blueprint.TemplateMob;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;
import software.bernie.geckolib.core.animation.AnimationState;

/** Shared loading; each profession owns an independently authored articulated rig. */
public final class TemplateMobModel extends GeoModel<TemplateMob> {
    @Override public void setCustomAnimations(TemplateMob mob, long instanceId, AnimationState<TemplateMob> state) {
        super.setCustomAnimations(mob, instanceId, state);
        TemplateSecondaryMotion.apply(this, mob, state.getPartialTick());
        if(mob.kind()==TemplateMob.Kind.DROWNER&&mob.isAlive()){
            boolean pool=mob.waterPool();
            getBone("body").ifPresent(b->{b.setScaleY(pool?.12F:1);b.setScaleX(pool?2.5F:1);b.setScaleZ(pool?2.5F:1);});
        }
        if(mob.kind()==TemplateMob.Kind.TOAD)
            // Independent identity wrapper: never multiply a shared animated bone across draws.
            getBone("tongue_reach").ifPresent(b->b.setScaleZ(mob.skillId()==com.dynasty.blueprint.ArmySkills.TOAD_TONGUE?mob.tongueReach()/5:1));
